CREATE TABLE ocr_batches (id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,owner_id TEXT NOT NULL REFERENCES user(id),version_id TEXT NOT NULL REFERENCES source_versions(id),connection_id TEXT NOT NULL,locale TEXT NOT NULL,budget_units INTEGER NOT NULL CHECK(budget_units>0),price TEXT NOT NULL CHECK(json_valid(price)),status TEXT NOT NULL CHECK(status IN ('staging','queued','running','paused','cancelled','completed','attention','stale')),detail TEXT NOT NULL DEFAULT '',storage_reserved INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX ocr_batch_owner_active ON ocr_batches(owner_id) WHERE status IN ('staging','queued','running','paused','attention');
CREATE INDEX ocr_batch_recovery ON ocr_batches(status,updated_at);
CREATE TABLE ocr_batch_pages (batch_id TEXT NOT NULL REFERENCES ocr_batches(id) ON DELETE CASCADE,page INTEGER NOT NULL CHECK(page>0),run_id TEXT NOT NULL UNIQUE,image_path TEXT NOT NULL DEFAULT '',image_hash TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','staged','running','review','attention')),detail TEXT NOT NULL DEFAULT '',PRIMARY KEY(batch_id,page));
CREATE TABLE source_derivations (version_id TEXT PRIMARY KEY REFERENCES source_versions(id),project_id TEXT NOT NULL REFERENCES projects(id),parent_version_id TEXT NOT NULL REFERENCES source_versions(id),run_id TEXT REFERENCES research_runs(id),page INTEGER,reviewer TEXT NOT NULL REFERENCES user(id),reason TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TRIGGER immutable_derivation_update BEFORE UPDATE ON source_derivations BEGIN SELECT RAISE(ABORT,'Derivations are immutable'); END;
CREATE TRIGGER immutable_derivation_delete BEFORE DELETE ON source_derivations WHEN NOT EXISTS(SELECT 1 FROM project_lifecycle WHERE project_id=old.project_id AND state='deleting') BEGIN SELECT RAISE(ABORT,'Derivations are immutable'); END;
